namespace Framework.Movement
{
    /// <summary>
    /// グリッド経路追従の失敗理由を表す。
    /// </summary>
    public enum GridPathFailureReason
    {
        /// <summary>
        /// 失敗が発生していない状態。
        /// </summary>
        None = 0,

        /// <summary>
        /// 次のセルへ進入できない状態。
        /// </summary>
        CellBlocked = 1,

        /// <summary>
        /// 経路上に存在しないセルへ到達した状態。
        /// </summary>
        UnexpectedCell = 2,

        /// <summary>
        /// 目的地へ到達する前に移動が停止した状態。
        /// </summary>
        MovementStopped = 3,

        /// <summary>
        /// 外部処理によって座標が変更された状態。
        /// </summary>
        Teleported = 4,

        /// <summary>
        /// 移動方向の要求が拒否された状態。
        /// </summary>
        DirectionRejected = 5
    }
}
